import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int bufLen, bufPtr;

    static int read() throws IOException {
        if (bufPtr == bufLen) {
            bufLen = System.in.read(BUF, 0, BUF.length);
            bufPtr = 0;
            if (bufLen <= 0) return -1;
        }
        return BUF[bufPtr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // Key = value * 64 + original position (n <= 50), sorted by value.
        long[] b = new long[n];
        for (int i = 0; i < n; i++) b[i] = nextLong() << 6 | i;
        Arrays.sort(b);
        // Threshold v is required exactly when its predecessor in sorted order sits to its right.
        StringBuilder out = new StringBuilder();
        for (int i = 1; i < n; i++) {
            if ((b[i - 1] & 63) > (b[i] & 63)) {
                if (out.length() > 0) out.append(' ');
                out.append(b[i] >> 6);
            }
        }
        System.out.println(out.length() > 0 ? out.toString() : "-1");
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	// Key = value * 64 + original position (n <= 50), sorted by value.
	b := make([]int64, n)
	for i := range b {
		b[i] = nextInt()<<6 | int64(i)
	}
	slices.Sort(b)
	// Threshold v is required exactly when its predecessor in sorted order sits to its right.
	var out []byte
	for i := 1; i < n; i++ {
		if b[i-1]&63 > b[i]&63 {
			if len(out) > 0 {
				out = append(out, ' ')
			}
			out = strconv.AppendInt(out, b[i]>>6, 10)
		}
	}
	if len(out) == 0 {
		out = append(out, "-1"...)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
